package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.chronicle.*; import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest; import net.fabricmc.fabric.api.client.gametest.v1.context.*; import net.minecraft.client.Minecraft; import java.util.*; @SuppressWarnings("UnstableApiUsage") public final class ChronicleClientGameTest implements FabricClientGameTest{public void runTest(ClientGameTestContext context){try(TestSingleplayerContext sp=context.worldBuilder().create()){sp.getClientLevel().waitForChunksRender();Minecraft.getInstance().gui.setScreen(new ChronicleScreen(List.of("TIMELINE","test event","PEOPLE","Villager","RELATIONSHIPS","trust=50","FAMILIES","PARENT","VILLAGES","population=2")));if(!(Minecraft.getInstance().gui.screen() instanceof ChronicleScreen))throw new AssertionError("Chronicle screen did not open");context.takeScreenshot("chronicle-screen");Minecraft.getInstance().gui.setScreen(null);}}}
